group-anagrams.solution:
class Solution:
    def groupAnagrams(self, strs):
        groups = {}
        for w in strs:
            count = [0] * 26
            for ch in w:
                count[ord(ch) - 97] += 1
            groups.setdefault(tuple(count), []).append(w)
        return list(groups.values())

