subarray-sum-equals-k.solution:
class Solution:
    def subarraySum(self, nums, k):
        seen = {0: 1}          # prefix sum -> how many times it has occurred
        total = count = 0
        for x in nums:
            total += x
            count += seen.get(total - k, 0)
            seen[total] = seen.get(total, 0) + 1
        return count

