class Solution:
    def removeDuplicates(self, nums):
        w = 1                                  # nums[:w] is the deduplicated prefix
        for r in range(1, len(nums)):
            if nums[r] != nums[w - 1]:
                nums[w] = nums[r]
                w += 1
        return w

