4sum.solution:
class Solution:
    def fourSum(self, nums, target):
        nums = sorted(nums)
        n, res = len(nums), []
        for i in range(n - 3):
            if i > 0 and nums[i] == nums[i - 1]:
                continue
            for j in range(i + 1, n - 2):
                if j > i + 1 and nums[j] == nums[j - 1]:
                    continue
                need = target - nums[i] - nums[j]
                l, r = j + 1, n - 1
                while l < r:
                    s = nums[l] + nums[r]
                    if s < need:
                        l += 1
                    elif s > need:
                        r -= 1
                    else:
                        res.append([nums[i], nums[j], nums[l], nums[r]])
                        l += 1
                        r -= 1
                        while l < r and nums[l] == nums[l - 1]:
                            l += 1
        return res

