container-with-most-water.solution:
class Solution:
    def maxArea(self, height):
        l, r = 0, len(height) - 1
        best = 0
        while l < r:
            h = min(height[l], height[r])
            best = max(best, h * (r - l))
            if height[l] < height[r]:
                l += 1          # the shorter wall can't do better with any closer partner
            else:
                r -= 1
        return best

